package com.sih.support.controller; import com.sih.support.dto.SupportDtos.*; import com.sih.support.service.*; import jakarta.validation.*; import java.util.*; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; @RestController @RequestMapping("/api/v1/support") public class SupportController {final SupportWorkflowService s;public SupportController(SupportWorkflowService x){s=x;}@GetMapping("/meals")public List<Meal>meals(){return s.meals();}@PostMapping("/meals")@ResponseStatus(HttpStatus.CREATED)public Meal meal(@Valid @RequestBody MealReq r){return s.createMeal(r);}@PostMapping("/meals/{id}/prepare")public Meal prepare(@PathVariable Long id){return s.prepare(id);}@PostMapping("/meals/{id}/deliver")public Meal deliver(@PathVariable Long id){return s.deliver(id);}@GetMapping("/equipment")public List<Asset>assets(){return s.equipment();}@PostMapping("/equipment")@ResponseStatus(HttpStatus.CREATED)public Asset asset(@Valid @RequestBody EquipmentReq r){return s.createEquipment(r);}@GetMapping("/maintenance")public List<Work>work(){return s.work();}@PostMapping("/maintenance")@ResponseStatus(HttpStatus.CREATED)public Work work(@Valid @RequestBody WorkReq r){return s.createWork(r);}@PostMapping("/maintenance/{id}/complete")public Work done(@PathVariable Long id){return s.completeWork(id);}@GetMapping("/cleaning")public List<Cleaning>cleaning(){return s.cleaning();}@PostMapping("/cleaning")@ResponseStatus(HttpStatus.CREATED)public Cleaning cleaning(@Valid @RequestBody CleaningReq r){return s.createCleaning(r);}@PostMapping("/cleaning/{id}/complete")public Cleaning clean(@PathVariable Long id){return s.completeCleaning(id);}}